#include <linux/dm-ioctl.h>

static int check_guard(size_t len, size_t needed, struct dm_name_list *nl)
{
	if (len < needed || len < sizeof(nl->dev)) {
		return 1;
	}
	nl->dev = 0;
	return 0;
}

int main(void)
{
	return check_guard(0, 0, (struct dm_name_list *)0);
}

